-- Step 3: build the real tables from staging, converting text to dates and numbers.
-- TRY_CONVERT gives NULL (instead of an error) when a value cannot be converted;
-- NULLIF turns empty text into NULL. 03_checks.sql then looks for values that failed.
USE MedicalPractice;
GO

-- mimic.patients
DROP TABLE IF EXISTS mimic.patients;
CREATE TABLE mimic.patients ([subject_id] bigint NULL, [gender] nvarchar(500) NULL, [anchor_age] bigint NULL, [anchor_year] bigint NULL, [anchor_year_group] nvarchar(500) NULL, [dod] date NULL);
INSERT INTO mimic.patients SELECT TRY_CONVERT(bigint, NULLIF([subject_id],'')), NULLIF([gender],''), TRY_CONVERT(bigint, NULLIF([anchor_age],'')), TRY_CONVERT(bigint, NULLIF([anchor_year],'')), NULLIF([anchor_year_group],''), TRY_CONVERT(date, NULLIF([dod],'')) FROM stg.mimic_patients;
GO

-- mimic.admissions
DROP TABLE IF EXISTS mimic.admissions;
CREATE TABLE mimic.admissions ([subject_id] bigint NULL, [hadm_id] bigint NULL, [admittime] datetime2(0) NULL, [dischtime] datetime2(0) NULL, [deathtime] datetime2(0) NULL, [admission_type] nvarchar(500) NULL, [admit_provider_id] nvarchar(500) NULL, [admission_location] nvarchar(500) NULL, [discharge_location] nvarchar(500) NULL, [insurance] nvarchar(500) NULL, [language] nvarchar(500) NULL, [marital_status] nvarchar(500) NULL, [race] nvarchar(500) NULL, [edregtime] datetime2(0) NULL, [edouttime] datetime2(0) NULL, [hospital_expire_flag] bigint NULL);
INSERT INTO mimic.admissions SELECT TRY_CONVERT(bigint, NULLIF([subject_id],'')), TRY_CONVERT(bigint, NULLIF([hadm_id],'')), TRY_CONVERT(datetime2(0), NULLIF([admittime],'')), TRY_CONVERT(datetime2(0), NULLIF([dischtime],'')), TRY_CONVERT(datetime2(0), NULLIF([deathtime],'')), NULLIF([admission_type],''), NULLIF([admit_provider_id],''), NULLIF([admission_location],''), NULLIF([discharge_location],''), NULLIF([insurance],''), NULLIF([language],''), NULLIF([marital_status],''), NULLIF([race],''), TRY_CONVERT(datetime2(0), NULLIF([edregtime],'')), TRY_CONVERT(datetime2(0), NULLIF([edouttime],'')), TRY_CONVERT(bigint, NULLIF([hospital_expire_flag],'')) FROM stg.mimic_admissions;
GO

